    contrast: [['Porcentaje de aciertos', 'Respuestas correctas/total del simulacro privado', 'No es un puntaje psicométrico CNSC'], ['Resultado por dominio', 'Errores y aciertos por función/tema', 'Es inestable con muestras pequeñas'], ['Autoinforme', 'Respuesta de acuerdo sobre conductas', 'No integra una métrica de aciertos funcionales']],
