const topicEntries = Object.entries(subjects)

export const dianMasterTheoryQuestions: Question[] = topicEntries.map(([moduleId, subject]) => {
  const items = [
    { text: subject.assessment.right, rationale: subject.assessment.why, correct: true },
    { text: subject.assessment.wrongA, rationale: subject.assessment.avoidA, correct: false },
    { text: subject.assessment.wrongB, rationale: subject.assessment.avoidB, correct: false },
  ]
  const shift = Number(moduleId.slice(1)) % 3
  const options = [...items.slice(shift), ...items.slice(0, shift)].map((item, index) => ({ id: ['a','b','c'][index]!, text: item.text, rationale: item.rationale }))
  const isFunctional = Number(moduleId.slice(1)) >= 1 && Number(moduleId.slice(1)) <= 17
  return {
    id: `q-master-2026-${moduleId}`,
    moduleId,
    skillIds: [`master-${moduleId}`, ...(isFunctional ? ['razonamiento-aplicado'] : ['repaso-conceptual'])],
    type: isFunctional ? 'pjs' as const : 'single' as const,
    difficulty: isFunctional ? 4 as const : 3 as const,
    case: subject.assessment.case,
    stem: subject.assessment.ask,
    options,
    correctOptionId: options.find((item) => item.text === subject.assessment.right)!.id,
    explanation: subject.assessment.why,
    sourceIds: subject.sources,
    verifiedAt: '2026-10-12',
  }
})

export const dianMasterTheoryLessons: Lesson[] = topicEntries.map(([moduleId, subject]) => {
  const blocks: LessonBlock[] = [
    { type: 'lead', text: subject.conceptual },
    { type: 'definition', title: 'Fundamento y alcance: qué afirma realmente la regla', text: subject.distinction },
    { type: 'paragraph', text: subject.procedure },
    { type: 'comparison', title: 'Diferencias que determinan una decisión', columns: ['Concepto', 'Tratamiento válido', 'Error de interpretación'], rows: subject.contrast },
    { type: 'example', title: 'Expediente o situación trabajada', text: subject.worked },
    { type: 'steps', title: 'Método profesional de resolución', items: subject.steps },
    { type: 'rule', title: 'Si cambia un hecho, revisa la conclusión', text: subject.change },
    { type: 'trap', title: 'Error que debes poder identificar', text: subject.pitfall },
    { type: 'checkpoint', questionId: `q-master-2026-${moduleId}` },
    { type: 'sources', sourceIds: subject.sources },
  ]
  // El autoinforme se practica con su propio componente, no como prueba PJS con clave.
  if (['m18','m19','m20'].includes(moduleId)) {
    blocks.splice(8, 0, { type: 'behavior-simulator', title: 'Autoinforme de cuatro categorías', text: 'Responde según tu conducta habitual. Es un ejercicio formativo sin clave de acierto ni predicción psicométrica.', ...(dianAdvancedBehaviorStatements[moduleId] ? { statements: dianAdvancedBehaviorStatements[moduleId] } : {}) })
  }
  return {
    id: `${moduleId}-master-2026`, moduleId, order: 0,
    title: subject.title, subtitle: 'Teoría fundamental ampliada · expediente resuelto · práctica razonada',
    durationMinutes: 25, skillIds: [`master-${moduleId}`], status: 'published', blocks,
  }
})
